def add_checklists(apps, schema_editor):
    """Give existing cases the research form's appliances / furniture checklist."""
    from cases.models import HouseholdItem as Live
    Beneficiary = apps.get_model("cases", "Beneficiary")
    Item = apps.get_model("cases", "HouseholdItem")
    rows = [Item(beneficiary_id=pk, item=code, kind=kind)
            for pk in Beneficiary.objects.values_list("pk", flat=True) for code, kind, _label in Live.ITEMS]
    Item.objects.bulk_create(rows, ignore_conflicts=True)


